from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==g[r][c]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(comp)
    return out
